def squash(s: str) -> str:
    result = []
    n = len(s)
    i = 0

    while i < n:
        c = s[i]
        j = i + 1
        while j < n and s[j] == c:
            j += 1

        escaped = "\\" + c if c == "\\" or "0" <= c <= "9" else c
        count = j - i

        if count >= 3:
            result.append(str(count) + escaped)
        else:
            result.append(escaped * count)

        i = j

    return "".join(result)
